    def check_password(self, email, password):
        if email in self.users and self.users[email].password == password:
            return True
        else:
            return False

    def change_email(self, old_email, new_email, confirm_password):
        if self.check_password(old_email, confirm_password):
            for k, v in self.users.items():
                if v.email == old_email:
                    v.email = new_email
                    break
            print(f"Email changed successfully from {old_email} to {new_email}.")
        else:
            print("Incorrect password. Email change failed.")

    def login(self, email, password):
        if email in self.users and self.users[email].password == password:
            return True
        else:
            return False

def main():
    login_system = LoginSystem()

    # Add users
    user1 = User("user1@example.com")
    user2 = User("user2@example.com")

    login_system.add_user(user1)
    login_system.add_user(user2)

    while True:
        print("\n1. Login\n2. Change email\n3. Quit")
        choice = input("Choose an option: ")

        if choice == "1":
            email = input("Enter your email: ")
            password = input("Enter your password: ")

            if login_system.login(email, password):
                while True:
                    print("\n1. Change email\n2. Logout\n3. Quit")
                    change_choice = input("Choose an option: ")

                    if change_choice == "1":
                        old_email = email
                        new_email = input("Enter your new email: ")
                        confirm_password = input("Confirm password: ")

                        login_system.change_email(old_email, new_email, confirm_password)
                    elif change_choice == "2":
                        print("Logged out successfully.")
                        break
                    elif change_choice == "3":
                        print("Goodbye!")
                        exit()
                    else:
                        print("Invalid choice. Please choose a valid option.")

                break
            else:
                print("Incorrect email or password. Try again.")

        elif choice == "2":
            old_email = input("Enter your old email: ")
            new_email = input("Enter your new email: ")
            confirm_password = input("Confirm password: ")

            login_system.change_email(old_email, new_email, confirm_password)

        elif choice == "3":
            print("Goodbye!")
            exit()

        else:
            print("Invalid choice. Please choose a valid option.")

if __name__ == "__main__":
    main()
```

In this script, we have two classes: `User` and `LoginSystem`. The `User` class represents a user with an email address and a password. The `LoginSystem` class manages the users and provides methods to check passwords, change emails, and log in.

The `main` function is where the program starts. It creates a `LoginSystem`, adds some users, and then enters a loop where it repeatedly asks for user input until the user chooses to quit. If the user chooses to login, they are prompted to enter their email and password. If the login is successful, they can choose to change their email or log out.

If the user chooses to change their email, they are prompted to enter their old email, new email, and confirm password. The program then checks if the old email and confirm password match, and if so, it changes the email.

This script does not store passwords securely (it uses plain text), which is a bad practice in real-world applications. It also doesn't handle errors very well, for example, what happens if you try to change your email when you're not logged in?']

