// Function to calculate the checksum of a given buffer
unsigned int calculate_checksum(char* buffer, unsigned int len) {
    unsigned int sum = 0;
    for (int i = 0; i < len; i++) {
        sum += (unsigned char)buffer[i];
    }
    return sum;
}

// Main function to read file contents and save the checksum
int main() {
    FILE* fptr;
    char buffer[1024]; // Buffer size can be adjusted as per requirement

    // Open the input file in binary mode
    fptr = fopen("input.txt", "rb");
    if (fptr == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    // Read the contents of the file into the buffer
    int bytes_read = 0;
    while ((buffer[bytes_read] = fgetc(fptr)) != EOF && bytes_read < sizeof(buffer) - 1) {
        bytes_read++;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the buffer

    // Calculate the checksum of the buffer
    unsigned int checksum = calculate_checksum(buffer, bytes_read);

    if (checksum == 0) {
        printf("Buffer is empty\n");
    } else {
        printf("Checksum: %u\n", checksum);
    }

    // Save the number of bytes read and the checksum to a file
    FILE* outptr;
    outptr = fopen("output.txt", "w");
    if (outptr == NULL) {
        printf("Error opening output file\n");
        return -1;
    }
    fprintf(outptr, "%d %u\n", bytes_read, checksum);
    fclose(outptr);

    // Close the input file
    fclose(fptr);
    return 0;
}
```

