```c
#include <httpd.h>
#include <apr_uri.h>

#define HELLO_PAGE "/hello"

static int http_hello_page(request_rec r) {
    // Get the username from the request body
    apr_pool_t *pool = r->pool;
    const char* username = NULL;
    apr_size_t len = 0;
    apr_file_read_all(&r->request_body, &username, &len);

    // Construct the response body (the HTML page)
    char* outputbuf = apr_palloc(pool, strlen("Hello, ") + len + strlen("</p>\n"));
    apr_snprintf(outputbuf, strlen("Hello, ") + len + strlen("</p>\n"), "Hello, %s</p>\n", username);

    // Write the response body to the response stream
    apr_file_write_all(&r->rfile, outputbuf, strlen(outputbuf));

    return HTTP_OK;
}

int main() {
    httpd_config *config = httpd_config_create();
    config->args = apr_pstrcat(config->pool, "ServerName localhost Port 8080\n", HELLO_PAGE, " /hello_page\n", NULL);
    httpdrve(config);

    return 0;
}
```

