void http_hello_page(FILE* request, FILE* response) {
    char username[256];
    fread(username, 1, 255, request); // read username from request stream
    username[255] = '\0'; // null-terminate the string

    char* greeting = malloc(strlen("Hello ") + strlen(username) + 2);
    strcpy(greeting, "Hello ");
    strcat(greeting, username);
