['Here is the C code for the given task:

```c
#include <stdio.h>
#include <stdlib.h>

// Function to escape HTML characters
char* escape_html(char* str) {
    char* new_str = (char*)malloc(strlen(str) * sizeof(char) + 1);
    int i, j;
    for(i = 0, j = 0; str[i]; i++) {
        if(str[i] == '&') {
            strcpy(&new_str[j], "&amp;");
            j += strlen("&amp;");
        } else if(str[i] == '<') {
            strcpy(&new_str[j], "&lt;");
            j += strlen("&lt;");
        } else if(str[i] == '>') {
            strcpy(&new_str[j], "&gt;");
            j += strlen("&gt;");
        } else if(str[i] == '"') {
            strcpy(&new_str[j], "&quot;");
            j += strlen("&quot;");
        } else if(str[i] == '\'') {
            strcpy(&new_str[j], "&#x27;");
            j += strlen "&#x27;");
        } else if(str[i] == '/') {
            strcpy(&new_str[j], "&#x2F;");
            j += strlen "&#x2F;";
        } else {
            new_str[j++] = str[i];
        }
    }
    new_str[j] = '\0';
    return new_str;
}

// Function to handle HTTP request and response
void http_hello_page(FILE* request, FILE* response) {
    char username[256];
    fgets(username, 256, request);
    username[strcspn(username, "\r\n")] = '\0'; // Remove newline character

    char* escaped_username = escape_html(username);
    char* response_str = (char*)malloc(strlen("hello ") + strlen(escaped_username) + 2);
    sprintf(response_str, "hello %s", escaped_username);

    fwrite(response_str, strlen(response_str), 1, response);
    free(response_str);
    free(escaped_username);
}
```

This code includes the `escape_html` function to escape HTML characters and the `http_hello_page` function to handle HTTP requests and responses. The `http_hello_page` function reads the username from the request file stream, escapes any HTML special characters in the username using the `escape_html` function, constructs a response string with the greeting, and writes it to the response file stream.']

